const PHASES = [
  { n: 1, metal: "gold" },
  { n: 2, metal: "copper" },
  { n: 3, metal: "silver" },
];

/* ---------- seven-segment digits (same as the HA card) ---------- */
const SEG = { "0": "abcdef", "1": "bc", "2": "abged", "3": "abgcd", "4": "fgbc", "5": "afgcd", "6": "afgedc", "7": "abc", "8": "abcdefg", "9": "abcdfg", "-": "g", " ": "" };
const DW = 26, DH = 46, ST = 5.4, GAP = 1.2, SLOT = 34;
function segPolys(x0) {
  const t = ST, h2 = DH / 2, g = GAP;
  const hz = (x, y, w) => `${x + g + t / 2},${y} ${x + g + t},${y - t / 2} ${x + w - g - t},${y - t / 2} ${x + w - g - t / 2},${y} ${x + w - g - t},${y + t / 2} ${x + g + t},${y + t / 2}`;
  const vt = (x, y, hh) => `${x},${y + g + t / 2} ${x + t / 2},${y + g + t} ${x + t / 2},${y + hh - g - t} ${x},${y + hh - g - t / 2} ${x - t / 2},${y + hh - g - t} ${x - t / 2},${y + g + t}`;
  const L = x0 + t / 2, R = x0 + DW - t / 2;
  return { a: hz(x0, t / 2, DW), g: hz(x0, h2, DW), d: hz(x0, DH - t / 2, DW), f: vt(L, t / 2, h2 - t / 2), b: vt(R, t / 2, h2 - t / 2), e: vt(L, h2, h2 - t / 2), c: vt(R, h2, h2 - t / 2) };
}
function sevenSeg(text, slots) {
  const chars = [];
  let dp = -1;
  for (const ch of text) { if (ch === ".") dp = chars.length - 1; else chars.push(ch); }
  while (chars.length < slots) { chars.unshift(" "); if (dp >= 0) dp++; }
  const w = slots * SLOT;
  let s = `<svg viewBox="-4 -1 ${w + 6} ${DH + 2}" aria-hidden="true"><defs><linearGradient id="gl" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff3c4"/><stop offset=".45" stop-color="#e8bf55"/><stop offset=".55" stop-color="#c8972f"/><stop offset="1" stop-color="#f2d27a"/></linearGradient></defs><g transform="skewX(-7)">`;
  chars.forEach((ch, i) => {
    const p = segPolys(i * SLOT + 6);
    const lit = SEG[ch] ?? "";
    for (const k of "abcdefg") s += `<polygon class="${lit.includes(k) ? "on" : "off"}" points="${p[k]}"/>`;
    s += `<rect class="${i === dp ? "on" : "off"}" x="${i * SLOT + 6 + DW + 1.5}" y="${DH - ST}" width="${ST}" height="${ST}" rx="1"/>`;
  });
  return s + "</g></svg>";
}

/* ---------- helpers ---------- */
const $ = (root, sel) => root.querySelector(sel);
const isNum = (v) => typeof v === "number" && Number.isFinite(v);
const clamp = (v, lo, hi) => Math.min(hi, Math.max(lo, v));
const money = (v, d = 2) => (isNum(v) ? `₪${Math.abs(v).toLocaleString("en-US", { minimumFractionDigits: d, maximumFractionDigits: d })}` : "—");
const fixed = (v, d) => (isNum(v) ? v.toFixed(d) : "—");
// keep "23:00–07:00" in reading order inside Hebrew text
const ltrTimes = (html) => html.replace(/(\d{1,2}:\d{2})\s*[–-]\s*(\d{1,2}:\d{2})/g, '<bdi dir="ltr">$1–$2</bdi>');
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

function duration(sec) {
  if (!isNum(sec)) return "—";
  const d = Math.floor(sec / 86400), h = Math.floor((sec % 86400) / 3600), m = Math.floor((sec % 3600) / 60);
  if (d) return `${d} ימים ו-${h} שעות`;
  if (h) return `${h} שעות ו-${m} דק׳`;
  return `${m} דק׳`;
}

/* ---------- styles ---------- */
const CSS = `
:root {
  --bg: #12110f;
  --panel: #1b1a16;
  --panel-2: #24221c;
  --line: rgba(232, 191, 85, 0.16);
  --line-2: rgba(232, 191, 85, 0.32);
  --ink: #f4eee0;
  --ink-2: #c3b79c;
  --ink-3: #8a7f67;
  --gold: #e8bf55;
  --gold-hi: #fff3c4;
  --gold-lo: #b8862b;
  --gold-grad: linear-gradient(135deg, #fff1b8 0%, #e8bf55 38%, #b8862b 62%, #f2d27a 100%);
  --on-gold: #241a05;
  --ok: #a6d38b;
  --warn: #f0a24a;
  --bad: #f06a5a;
  --metal-gold: linear-gradient(90deg, #8a6418, #e8bf55 55%, #fff1b8);
  --metal-copper: linear-gradient(90deg, #6e3a1c, #c9773f 55%, #f3b98b);
  --metal-silver: linear-gradient(90deg, #5b6068, #b9c0c8 55%, #f2f5f8);
  --r-lg: 18px;
  --r-md: 12px;
  color-scheme: dark;
}
* { box-sizing: border-box; }
html, body { margin: 0; background: var(--bg); }
body {
  min-height: 100vh;
  color: var(--ink);
  font: 15px/1.5 -apple-system, "Segoe UI", Roboto, "Noto Sans Hebrew", "Arial Hebrew", Arial, sans-serif;
  font-variant-numeric: tabular-nums;
  background:
    radial-gradient(120% 60% at 50% -10%, rgba(232, 191, 85, 0.13), transparent 60%),
    var(--bg);
  -webkit-font-smoothing: antialiased;
}
esp-app { display: block; max-width: 560px; margin: 0 auto; padding: 0 16px 48px; }
button, input, select { font: inherit; color: inherit; }
button { cursor: pointer; }
:focus-visible { outline: 2px solid var(--gold-hi); outline-offset: 2px; }
[hidden] { display: none !important; }

/* header */
.top {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 18px 0 14px;
}
.mark {
  width: 38px; height: 38px; flex: none;
  border-radius: 12px;
  background: var(--gold-grad);
  display: grid; place-items: center;
  box-shadow: 0 6px 18px rgba(232, 191, 85, 0.25), inset 0 1px 0 rgba(255, 255, 255, 0.5);
}
.mark svg { width: 20px; height: 20px; fill: var(--on-gold); }
.who { flex: 1; min-width: 0; }
.who h1 { margin: 0; font-size: 17px; font-weight: 650; letter-spacing: -0.01em; }
.who p { margin: 0; font-size: 12.5px; color: var(--ink-3); direction: ltr; text-align: right; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.pill {
  display: inline-flex; align-items: center; gap: 7px;
  padding: 5px 11px;
  border-radius: 999px;
  border: 1px solid var(--line);
  background: var(--panel);
  font-size: 12.5px; color: var(--ink-2);
  white-space: nowrap;
}
.pill i { width: 8px; height: 8px; border-radius: 50%; background: var(--ink-3); }
.pill.ok i { background: var(--ok); box-shadow: 0 0 8px var(--ok); }
.pill.bad i { background: var(--bad); box-shadow: 0 0 8px var(--bad); }

.banner {
  margin: 0 0 12px;
  padding: 10px 14px;
  border-radius: var(--r-md);
  background: rgba(240, 106, 90, 0.12);
  border: 1px solid rgba(240, 106, 90, 0.35);
  color: #ffd2cb;
  font-size: 13.5px;
}

/* tabs */
.tabs {
  position: sticky; top: 0; z-index: 5;
  display: grid; grid-template-columns: repeat(4, 1fr);
  gap: 4px;
  padding: 4px;
  margin: 0 0 16px;
  border-radius: 14px;
  background: rgba(27, 26, 22, 0.86);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border: 1px solid var(--line);
}
.tabs button {
  border: 0; background: none;
  padding: 9px 2px;
  border-radius: 10px;
  font-size: 13.5px; color: var(--ink-2);
  white-space: nowrap;
}
.tabs button[aria-selected="true"] {
  background: var(--gold-grad);
  color: var(--on-gold);
  font-weight: 650;
  box-shadow: 0 4px 14px rgba(232, 191, 85, 0.25);
}

/* panels */
.panel {
  background: linear-gradient(180deg, var(--panel-2), var(--panel));
  border: 1px solid var(--line);
  border-radius: var(--r-lg);
  padding: 16px;
  margin-bottom: 12px;
}
.panel h2 { margin: 0 0 4px; font-size: 15px; font-weight: 650; }
.panel .hint { margin: 0 0 14px; font-size: 13px; color: var(--ink-3); }

/* hero */
.hero { text-align: center; padding: 22px 16px 18px; }
.lcd { display: inline-flex; align-items: flex-end; gap: 8px; direction: ltr; }
.lcd svg { width: min(250px, 64vw); height: auto; }
.lcd .on { fill: url(#gl); filter: drop-shadow(0 0 6px rgba(232, 191, 85, 0.35)); }
.lcd .off { fill: rgba(232, 191, 85, 0.06); }
.lcd .unit { font-size: 18px; color: var(--ink-2); padding-bottom: 6px; }
.hero .what { margin: 4px 0 14px; font-size: 13.5px; color: var(--ink-3); }
.hero .what.export { color: var(--ok); }
.duo { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.duo div { padding: 10px; border-radius: var(--r-md); background: rgba(0, 0, 0, 0.18); border: 1px solid var(--line); }
.duo b { display: block; font-size: 19px; font-weight: 650; direction: ltr; }
.duo span { font-size: 12.5px; color: var(--ink-3); }

/* phase busbars */
.bus { display: grid; gap: 14px; }
.ph { display: grid; grid-template-columns: 64px 1fr; gap: 6px 12px; align-items: center; }
.ph .name { font-size: 13.5px; color: var(--ink-2); }
.ph .track {
  position: relative;
  height: 14px;
  border-radius: 7px;
  background: rgba(0, 0, 0, 0.35);
  border: 1px solid var(--line);
  overflow: hidden;
}
.ph .fill {
  position: absolute; inset: 0 auto 0 0;
  width: 0;
  border-radius: 7px;
  transition: width 700ms cubic-bezier(.2, .8, .2, 1);
}
[dir="rtl"] .ph .fill { inset: 0 0 0 auto; }
.ph.gold .fill { background: var(--metal-gold); }
.ph.copper .fill { background: var(--metal-copper); }
.ph.silver .fill { background: var(--metal-silver); }
[dir="rtl"] .ph .fill { transform: scaleX(-1); }
.ph.warn .fill { background: linear-gradient(90deg, #7a3f0e, var(--warn)); }
.ph.crit .fill { background: linear-gradient(90deg, #6e1d15, var(--bad)); }
.ph .mark80 { position: absolute; top: -2px; bottom: -2px; width: 0; border-inline-start: 1px dashed rgba(240, 162, 74, 0.7); inset-inline-start: 80%; }
.ph .nums { grid-column: 2; display: flex; gap: 14px; font-size: 12.5px; color: var(--ink-3); direction: ltr; justify-content: flex-end; }
.ph .nums b { color: var(--ink); font-weight: 600; font-size: 14px; }
.ph.warn .nums b.a { color: var(--warn); }
.ph.crit .nums b.a { color: var(--bad); }

/* money tiles */
.tiles { display: grid; grid-template-columns: repeat(2, 1fr); gap: 10px; }
.tile { padding: 12px; border-radius: var(--r-md); background: rgba(0, 0, 0, 0.18); border: 1px solid var(--line); }
.tile b { display: block; font-size: 20px; font-weight: 650; direction: ltr; text-align: right; }
.tile span { font-size: 12.5px; color: var(--ink-3); }
.tile b.up { color: var(--bad); }
.tile b.down { color: var(--ok); }
.note { margin: 12px 0 0; font-size: 13px; color: var(--ink-3); }
.note b { color: var(--ink-2); font-weight: 600; }

/* plan list */
.now-price { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; padding: 12px 14px; margin-bottom: 14px; border-radius: var(--r-md); background: rgba(232, 191, 85, 0.08); border: 1px solid var(--line-2); }
.now-price b { font-size: 22px; font-weight: 700; background: var(--gold-grad); -webkit-background-clip: text; background-clip: text; color: transparent; direction: ltr; }
.now-price span { font-size: 13px; color: var(--ink-2); }
.search { width: 100%; margin-bottom: 10px; padding: 10px 12px; border-radius: var(--r-md); background: rgba(0, 0, 0, 0.25); border: 1px solid var(--line); }
.plans { display: grid; gap: 8px; max-height: 420px; overflow: auto; padding: 2px; }
.prov { margin: 8px 2px 2px; font-size: 12.5px; color: var(--gold); font-weight: 600; }
.plan {
  display: grid; grid-template-columns: 18px 1fr auto; gap: 10px; align-items: center;
  width: 100%;
  padding: 11px 12px;
  border-radius: var(--r-md);
  border: 1px solid var(--line);
  background: rgba(0, 0, 0, 0.2);
  text-align: start;
}
.plan .dot { width: 18px; height: 18px; border-radius: 50%; border: 2px solid var(--ink-3); }
.plan[aria-checked="true"] { border-color: var(--gold); background: rgba(232, 191, 85, 0.1); }
.plan[aria-checked="true"] .dot { border-color: var(--gold); background: radial-gradient(circle, var(--gold) 0 45%, transparent 50%); }
.plan .t { font-size: 14px; }
.plan .s { display: block; font-size: 12.5px; color: var(--ink-3); }
.plan .pct { font-weight: 700; color: var(--gold); direction: ltr; }
.plan.busy { opacity: 0.6; }

/* fields */
.field { display: grid; gap: 6px; margin-bottom: 14px; }
.field label { font-size: 13.5px; color: var(--ink-2); }
.field .row { display: flex; gap: 8px; }
.field input[type="number"] {
  flex: 1; min-width: 0;
  padding: 10px 12px;
  border-radius: var(--r-md);
  background: rgba(0, 0, 0, 0.25);
  border: 1px solid var(--line);
  direction: ltr; text-align: right;
}
.field small { font-size: 12.5px; color: var(--ink-3); }
.seg { display: flex; gap: 6px; flex-wrap: wrap; }
.seg button { padding: 8px 12px; border-radius: 999px; border: 1px solid var(--line); background: rgba(0, 0, 0, 0.2); }
.seg button[aria-pressed="true"] { border-color: var(--gold); color: var(--gold-hi); background: rgba(232, 191, 85, 0.12); }
.switch { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 10px 0; }
.switch button { width: 46px; height: 28px; border-radius: 14px; border: 1px solid var(--line-2); background: rgba(0, 0, 0, 0.3); position: relative; flex: none; }
.switch button::after { content: ""; position: absolute; top: 3px; inset-inline-start: 3px; width: 20px; height: 20px; border-radius: 50%; background: var(--ink-3); transition: inset-inline-start 160ms ease, background 160ms ease; }
.switch button[aria-checked="true"] { background: rgba(232, 191, 85, 0.25); border-color: var(--gold); }
.switch button[aria-checked="true"]::after { inset-inline-start: 21px; background: var(--gold); }

.btn {
  padding: 10px 16px;
  border-radius: var(--r-md);
  border: 1px solid var(--line-2);
  background: rgba(0, 0, 0, 0.2);
  color: var(--ink);
  font-weight: 600;
  white-space: nowrap;
}
.btn.primary { border: 0; background: var(--gold-grad); color: var(--on-gold); box-shadow: 0 6px 18px rgba(232, 191, 85, 0.22); }
.btn.danger { border-color: rgba(240, 106, 90, 0.45); color: #ffc2b9; }
.btn[disabled] { opacity: 0.5; cursor: default; }
.btn.saved { border-color: var(--ok); color: var(--ok); }
.actions { display: flex; gap: 8px; flex-wrap: wrap; }

/* update */
.ver { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; margin-bottom: 14px; }
.ver div { padding: 10px 12px; border-radius: var(--r-md); background: rgba(0, 0, 0, 0.2); border: 1px solid var(--line); }
.ver b { display: block; direction: ltr; text-align: right; font-size: 16px; }
.ver span { font-size: 12.5px; color: var(--ink-3); }
.drop {
  display: grid; place-items: center; gap: 6px;
  padding: 22px 14px;
  border-radius: var(--r-md);
  border: 1.5px dashed var(--line-2);
  background: rgba(0, 0, 0, 0.18);
  text-align: center;
  cursor: pointer;
}
.drop.over { border-color: var(--gold); background: rgba(232, 191, 85, 0.08); }
.drop b { font-weight: 600; }
.drop span { font-size: 12.5px; color: var(--ink-3); }
.progress { height: 10px; border-radius: 5px; background: rgba(0, 0, 0, 0.35); border: 1px solid var(--line); overflow: hidden; margin-top: 12px; }
.progress div { height: 100%; width: 0; background: var(--metal-gold); transition: width 200ms linear; }
.status { margin: 10px 0 0; font-size: 13.5px; color: var(--ink-2); min-height: 1.4em; }
.status.ok { color: var(--ok); }
.status.bad { color: var(--bad); }

/* device */
.kv { display: grid; grid-template-columns: auto 1fr; gap: 9px 16px; margin: 0; }
.kv dt { color: var(--ink-3); font-size: 13.5px; }
.kv dd { margin: 0; text-align: left; font-size: 14px; unicode-bidi: plaintext; }

@media (prefers-reduced-motion: reduce) {
  * { transition: none !important; animation: none !important; }
}
`;

/* ---------- the app ---------- */
class EspApp extends HTMLElement {
  constructor() {
    super();
    this.state = {};      // id -> last JSON from the device
    this.tab = "now";
    this.pending = {};    // inputs being edited, don't overwrite them
  }

  connectedCallback() {
    this.prepareDocument();
    this.render();
    this.connect();
  }

  prepareDocument() {
    const html = document.documentElement;
    html.lang = "he";
    html.dir = "rtl";
    if (!document.querySelector('meta[name="viewport"]')) {
      const m = document.createElement("meta");
      m.name = "viewport";
      m.content = "width=device-width, initial-scale=1, viewport-fit=cover";
      document.head.appendChild(m);
    }
    const tc = document.createElement("meta");
    tc.name = "theme-color";
    tc.content = "#12110f";
    document.head.appendChild(tc);
    const st = document.createElement("style");
    st.textContent = CSS;
    document.head.appendChild(st);
    document.title = "קורא מונה חשמל";
  }

  /* ----- data ----- */
  connect() {
    if (this.es) this.es.close();
    const es = new EventSource("/events");
    this.es = es;
    const onState = (e) => {
      try {
        const d = JSON.parse(e.data);
        if (!d.id) return;
        this.state[d.id] = { ...(this.state[d.id] || {}), ...d };
        this.scheduleUpdate();
      } catch (_) { /* ignore malformed */ }
    };
    es.addEventListener("state", onState);
    es.addEventListener("state_detail_all", onState);
    es.addEventListener("ping", (e) => {
      this.lastPing = Date.now();
      try {
        const d = JSON.parse(e.data || "{}");
        if (d.title) this.title = d.title;
      } catch (_) { /* ping can be empty */ }
      this.setOnline(true);
    });
    es.onopen = () => this.setOnline(true);
    es.onerror = () => this.setOnline(false);
    clearInterval(this.watch);
    this.watch = setInterval(() => {
      // The device pings every few seconds; silence means we lost it.
      if (this.lastPing && Date.now() - this.lastPing > 25000) this.setOnline(false);
    }, 5000);
  }

  setOnline(on) {
    if (this.online === on) return;
    this.online = on;
    this.scheduleUpdate();
  }

  scheduleUpdate() {
    if (this.raf) return;
    this.raf = requestAnimationFrame(() => {
      this.raf = 0;
      this.update();
    });
  }

  /** first entity whose id matches one of the names (domain/Name) */
  get(...ids) {
    for (const id of ids) if (this.state[id]) return this.state[id];
    return undefined;
  }
  num(...ids) {
    const s = this.get(...ids);
    if (!s) return NaN;
    const v = typeof s.value === "number" ? s.value : parseFloat(s.value);
    return Number.isFinite(v) ? v : NaN;
  }
  text(...ids) {
    const s = this.get(...ids);
    if (!s) return "";
    const v = s.state ?? s.value;
    return v === "NA" || v == null ? "" : String(v);
  }

  async post(id, action, params) {
    const [domain, ...rest] = id.split("/");
    const name = rest.join("/");
    const q = params ? `?${new URLSearchParams(params)}` : "";
    const r = await fetch(`/${domain}/${encodeURIComponent(name)}/${action}${q}`, { method: "POST" });
    if (!r.ok) throw new Error(`HTTP ${r.status}`);
  }

  /* ----- layout (built once) ----- */
  render() {
    const bolt = `<svg viewBox="0 0 24 24"><path d="M13.5 2 4 13.5h6.2L9 22l9.5-12h-6.3z"/></svg>`;
    this.innerHTML = `
      <header class="top">
        <div class="mark" aria-hidden="true">${bolt}</div>
        <div class="who"><h1>קורא מונה חשמל</h1><p id="host"></p></div>
        <span class="pill" id="pill"><i></i><span>מתחבר…</span></span>
      </header>
      <div class="banner" id="lost" hidden>החיבור למכשיר נותק. מנסה להתחבר שוב…</div>

      <nav class="tabs" role="tablist">
        <button role="tab" data-tab="now" aria-selected="true">עכשיו</button>
        <button role="tab" data-tab="plan" aria-selected="false">מסלול ומחיר</button>
        <button role="tab" data-tab="update" aria-selected="false">עדכון</button>
        <button role="tab" data-tab="device" aria-selected="false">מכשיר</button>
      </nav>

      <section data-view="now">
        <div class="panel hero">
          <div class="lcd" id="lcd"></div>
          <p class="what" id="what">צריכה עכשיו</p>
          <div class="duo">
            <div><b id="rate">—</b><span>עלות לשעה בקצב הזה</span></div>
            <div><b id="today">—</b><span>עלות היום עד עכשיו</span></div>
          </div>
        </div>

        <div class="panel">
          <h2>עומס על כל פאזה</h2>
          <p class="hint" id="bushint">הפס מראה כמה מהמפסק בשימוש.</p>
          <div class="bus">
            ${PHASES.map((p) => `
              <div class="ph ${p.metal}" id="ph${p.n}">
                <span class="name">פאזה ${p.n}</span>
                <div class="track"><div class="fill"></div><span class="mark80"></span></div>
                <div class="nums"><span><b class="a">—</b> A</span><span><b class="k">—</b> kW</span><span><b class="v">—</b> V</span></div>
              </div>`).join("")}
          </div>
        </div>

        <div class="panel">
          <h2>כסף</h2>
          <div class="tiles" style="margin-top:10px">
            <div class="tile"><b id="t-month">—</b><span>החודש עד עכשיו</span></div>
            <div class="tile"><b id="t-fc">—</b><span>צפי לסוף החודש</span></div>
            <div class="tile"><b id="t-kwh">—</b><span>קוט״ש היום</span></div>
            <div class="tile"><b id="t-vs">—</b><span id="t-vs-l">מול אתמול באותה שעה</span></div>
          </div>
          <p class="note" id="base"></p>
          <p class="note" id="peak"></p>
        </div>
      </section>

      <section data-view="plan" hidden>
        <div class="panel">
          <h2>מסלול הנחה</h2>
          <p class="hint">בחר את המסלול שלך אצל ספק החשמל. ההנחה מחושבת לפי השעה ביום.</p>
          <div class="now-price"><span id="pricewhy">המחיר עכשיו</span><b id="price">—</b></div>
          <input class="search" id="q" type="search" placeholder="חיפוש ספק או מסלול" aria-label="חיפוש ספק או מסלול">
          <div class="plans" id="plans" role="radiogroup" aria-label="מסלול הנחה"></div>
        </div>

        <div class="panel" id="custom" hidden>
          <h2>מסלול מותאם אישית</h2>
          <p class="hint">למסלול שלא מופיע ברשימה. מחוץ לחלון השעות חלה ההנחה הקבועה.</p>
          ${this.numField("number/Custom Discount", "הנחה קבועה", "%")}
          ${this.numField("number/Custom Window Discount", "הנחה בחלון השעות", "%")}
          <div class="field"><label>חלון השעות</label>
            <div class="row">
              <input type="number" min="0" max="23" step="1" data-num="number/Custom Window Start" aria-label="שעת התחלה">
              <input type="number" min="0" max="23" step="1" data-num="number/Custom Window End" aria-label="שעת סיום">
              <button class="btn" data-save="number/Custom Window Start,number/Custom Window End">שמירה</button>
            </div>
            <small>משעה עד שעה, למשל 23 עד 7. חלון שעובר את חצות נתמך.</small>
          </div>
          <div class="switch"><span>רק בימים א׳–ה׳</span><button role="switch" aria-checked="false" data-switch="switch/Custom Window Sun-Thu Only" aria-label="רק בימים א׳–ה׳"></button></div>
        </div>

        <div class="panel">
          <h2>תעריף ותשלום קבוע</h2>
          <p class="hint">התעריף של חברת החשמל לקוט״ש כולל מע״מ, לפני הנחה.</p>
          ${this.numField("number/Base Price", "תעריף לקוט״ש", "₪", "0.0001")}
          ${this.numField("number/Fixed Charge", "תשלום קבוע לחודש", "₪", "0.01")}
        </div>

        <div class="panel">
          <h2>המפסק הראשי</h2>
          <p class="hint">גודל המפסק לכל פאזה. לפיו נקבע מתי פאזה מתקרבת לעומס יתר.</p>
          <div class="seg" id="breaker">
            ${[25, 32, 40, 63].map((a) => `<button data-amps="${a}" aria-pressed="false"><bdi dir="ltr">3×${a}A</bdi></button>`).join("")}
          </div>
        </div>
      </section>

      <section data-view="update" hidden>
        <div class="panel">
          <h2>עדכון קושחה</h2>
          <div class="ver" style="margin-top:10px">
            <div><b id="v-cur">—</b><span>גרסה מותקנת</span></div>
            <div><b id="v-new">—</b><span>גרסה אחרונה</span></div>
          </div>
          <p class="hint" id="v-sum"></p>
          <div class="actions"><button class="btn primary" id="v-install" disabled>התקנת העדכון</button></div>
          <p class="status" id="v-status"></p>
        </div>
        <div class="panel">
          <h2>העלאת קובץ</h2>
          <p class="hint">לקובץ <b dir="ltr">.ota.bin</b> מעמוד ההורדות. קובץ factory לא מתאים כאן.</p>
          <label class="drop" id="drop">
            <input type="file" id="file" accept=".bin" hidden>
            <b>בחירת קובץ קושחה</b>
            <span>או גרירה לכאן</span>
          </label>
          <div class="progress" hidden id="bar"><div></div></div>
          <p class="status" id="up-status"></p>
        </div>
      </section>

      <section data-view="device" hidden>
        <div class="panel">
          <h2>מצב המכשיר</h2>
          <dl class="kv" style="margin-top:12px">
            <dt>נתונים מהמונה</dt><dd id="d-p1">—</dd>
            <dt>שגיאות CRC</dt><dd id="d-crc">—</dd>
            <dt>קליטת Wi-Fi</dt><dd id="d-wifi">—</dd>
            <dt>כתובת IP</dt><dd id="d-ip">—</dd>
            <dt>זמן פעולה</dt><dd id="d-up">—</dd>
            <dt>גרסה</dt><dd id="d-ver">—</dd>
          </dl>
        </div>
        <div class="panel">
          <h2>פעולות</h2>
          <p class="hint">לחיצה ראשונה מבקשת אישור.</p>
          <div class="actions">
            <button class="btn" data-press="button/Restart">הפעלה מחדש</button>
            <button class="btn" data-press="button/Safe Mode">מצב בטוח</button>
            <button class="btn danger" data-press="button/Reset Statistics">איפוס סטטיסטיקה</button>
          </div>
          <p class="status" id="act-status"></p>
        </div>
      </section>`;

    this.bind();
  }

  numField(id, label, unit, step = "1") {
    return `<div class="field"><label>${label}${unit ? ` (${unit})` : ""}</label>
      <div class="row"><input type="number" step="${step}" data-num="${id}" aria-label="${label}"><button class="btn" data-save="${id}">שמירה</button></div></div>`;
  }

  bind() {
    this.querySelectorAll("[data-tab]").forEach((b) => b.addEventListener("click", () => this.showTab(b.dataset.tab)));

    // number inputs: remember edits until saved
    this.querySelectorAll("[data-num]").forEach((inp) => {
      inp.addEventListener("input", () => (this.pending[inp.dataset.num] = true));
      inp.addEventListener("keydown", (e) => {
        if (e.key === "Enter") inp.closest(".row")?.querySelector("[data-save]")?.click();
      });
    });
    this.querySelectorAll("[data-save]").forEach((btn) => btn.addEventListener("click", async () => {
      const ids = btn.dataset.save.split(",");
      btn.disabled = true;
      try {
        for (const id of ids) {
          const inp = this.querySelector(`[data-num="${id}"]`);
          const v = parseFloat(inp.value);
          if (!Number.isFinite(v)) throw new Error("bad");
          await this.post(id, "set", { value: String(v) });
          delete this.pending[id];
        }
        this.flash(btn, "נשמר");
      } catch (_) {
        this.flash(btn, "לא נשמר", true);
      } finally {
        btn.disabled = false;
      }
    }));

    this.querySelectorAll("[data-switch]").forEach((sw) => sw.addEventListener("click", async () => {
      const on = sw.getAttribute("aria-checked") !== "true";
      sw.setAttribute("aria-checked", String(on));
      try { await this.post(sw.dataset.switch, on ? "turn_on" : "turn_off"); } catch (_) { sw.setAttribute("aria-checked", String(!on)); }
    }));

    this.querySelectorAll("[data-amps]").forEach((b) => b.addEventListener("click", async () => {
      try { await this.post("number/Breaker Size", "set", { value: b.dataset.amps }); } catch (_) { /* state event will correct it */ }
    }));

    // two-step confirm for device actions
    this.querySelectorAll("[data-press]").forEach((b) => b.addEventListener("click", async () => {
      const status = $(this, "#act-status");
      if (b.dataset.armed !== "1") {
        this.querySelectorAll("[data-press]").forEach((o) => { o.dataset.armed = ""; o.textContent = o.dataset.label || o.textContent; });
        b.dataset.label = b.textContent;
        b.dataset.armed = "1";
        b.textContent = "לחץ שוב לאישור";
        clearTimeout(this.armTimer);
        this.armTimer = setTimeout(() => { b.dataset.armed = ""; b.textContent = b.dataset.label; }, 4000);
        return;
      }
      b.dataset.armed = "";
      b.textContent = b.dataset.label;
      try {
        await this.post(b.dataset.press, "press");
        status.className = "status ok";
        status.textContent = b.dataset.press === "button/Reset Statistics" ? "הסטטיסטיקה אופסה." : "הפקודה נשלחה. המכשיר יחזור בעוד כחצי דקה.";
      } catch (_) {
        status.className = "status bad";
        status.textContent = "הפקודה לא נשלחה. בדוק את החיבור למכשיר.";
      }
    }));

    // plans
    $(this, "#q").addEventListener("input", () => this.renderPlans(true));
    $(this, "#plans").addEventListener("click", async (e) => {
      const b = e.target.closest(".plan");
      if (!b) return;
      b.classList.add("busy");
      try { await this.post("select/Supplier Plan", "set", { option: b.dataset.option }); }
      catch (_) { /* keep the old selection; state will tell */ }
      finally { b.classList.remove("busy"); }
    });

    // firmware
    $(this, "#v-install").addEventListener("click", async () => {
      const st = $(this, "#v-status");
      try {
        await this.post("update/Firmware", "install");
        st.className = "status";
        st.textContent = "מוריד ומתקין. המכשיר יופעל מחדש בסיום.";
        this.waitForReboot(st);
      } catch (_) {
        st.className = "status bad";
        st.textContent = "ההתקנה לא התחילה. בדוק שלמכשיר יש גישה לאינטרנט.";
      }
    });
    const drop = $(this, "#drop");
    const file = $(this, "#file");
    file.addEventListener("change", () => file.files[0] && this.upload(file.files[0]));
    drop.addEventListener("dragover", (e) => { e.preventDefault(); drop.classList.add("over"); });
    drop.addEventListener("dragleave", () => drop.classList.remove("over"));
    drop.addEventListener("drop", (e) => {
      e.preventDefault();
      drop.classList.remove("over");
      const f = e.dataTransfer.files[0];
      if (f) this.upload(f);
    });
  }

  flash(btn, text, bad) {
    const old = btn.dataset.label || btn.textContent;
    btn.dataset.label = old;
    btn.textContent = text;
    btn.classList.toggle("saved", !bad);
    clearTimeout(btn._t);
    btn._t = setTimeout(() => { btn.textContent = old; btn.classList.remove("saved"); }, 1800);
  }

  showTab(tab) {
    this.tab = tab;
    this.querySelectorAll("[data-tab]").forEach((b) => b.setAttribute("aria-selected", String(b.dataset.tab === tab)));
    this.querySelectorAll("[data-view]").forEach((v) => (v.hidden = v.dataset.view !== tab));
    this.update();
  }

  upload(f) {
    const st = $(this, "#up-status");
    const bar = $(this, "#bar");
    if (!/\.bin$/i.test(f.name)) {
      st.className = "status bad";
      st.textContent = "צריך קובץ ‎.bin‎.";
      return;
    }
    if (/factory/i.test(f.name)) {
      st.className = "status bad";
      st.textContent = "זה קובץ factory. כאן מעלים את קובץ ה-‎.ota.bin‎.";
      return;
    }
    const fd = new FormData();
    fd.append("update", f, f.name);
    const xhr = new XMLHttpRequest();
    bar.hidden = false;
    st.className = "status";
    st.textContent = `מעלה את ${f.name}…`;
    xhr.upload.onprogress = (e) => {
      if (e.lengthComputable) bar.firstElementChild.style.width = `${Math.round((e.loaded / e.total) * 100)}%`;
    };
    xhr.onload = () => {
      if (xhr.status === 200) {
        bar.firstElementChild.style.width = "100%";
        st.className = "status ok";
        st.textContent = "העדכון הותקן. המכשיר מופעל מחדש…";
        this.waitForReboot(st);
      } else {
        st.className = "status bad";
        st.textContent = `העדכון נכשל (${xhr.status}). המכשיר ממשיך לעבוד עם הגרסה הקודמת.`;
      }
    };
    xhr.onerror = () => {
      st.className = "status bad";
      st.textContent = "החיבור נקטע באמצע ההעלאה. נסה שוב.";
    };
    xhr.open("POST", "/update");
    xhr.send(fd);
  }

  waitForReboot(st) {
    const started = Date.now();
    const tick = async () => {
      try {
        const r = await fetch("/", { cache: "no-store" });
        if (r.ok && Date.now() - started > 8000) {
          st.className = "status ok";
          st.textContent = "המכשיר חזר לפעול.";
          setTimeout(() => location.reload(), 1200);
          return;
        }
      } catch (_) { /* still rebooting */ }
      if (Date.now() - started < 120000) setTimeout(tick, 2500);
      else { st.className = "status bad"; st.textContent = "המכשיר לא חזר אחרי שתי דקות. בדוק אותו בלוח החשמל."; }
    };
    setTimeout(tick, 4000);
  }

  /* ----- update on data ----- */
  update() {
    const online = this.online !== false;
    $(this, "#lost").hidden = online || this.online === undefined;

    const p1 = this.get("binary_sensor/P1 Data");
    const power = this.num("sensor/Power");
    const exp = this.num("sensor/Power Export");
    const reading = p1 ? p1.value === true || p1.state === "ON" : isNum(power);
    const pill = $(this, "#pill");
    pill.className = `pill ${online && reading ? "ok" : "bad"}`;
    pill.lastElementChild.textContent = !online ? "לא מחובר" : reading ? "קורא מהמונה" : "אין נתונים מהמונה";
    $(this, "#host").textContent = location.host;

    if (this.tab === "now") this.updateNow(power, exp);
    if (this.tab === "plan") this.updatePlan();
    if (this.tab === "update") this.updateFirmware();
    if (this.tab === "device") this.updateDevice(reading);
  }

  updateNow(power, exp) {
    const exporting = isNum(exp) && exp > 0.005 && !(power > 0.005);
    const shown = exporting ? -exp : power;
    const txt = isNum(shown) ? (Math.abs(shown) >= 10 ? shown.toFixed(1) : shown.toFixed(2)) : "    ";
    if (txt !== this.lcdTxt) {
      this.lcdTxt = txt;
      $(this, "#lcd").innerHTML = `${sevenSeg(txt, 5)}<span class="unit">kW</span>`;
    }
    const what = $(this, "#what");
    what.textContent = exporting ? "מחזיר לרשת עכשיו" : isNum(power) ? "צריכה עכשיו" : "ממתין לנתונים מהמונה";
    what.classList.toggle("export", exporting);

    $(this, "#rate").textContent = money(this.num("sensor/Cost Now"));
    $(this, "#today").textContent = money(this.num("sensor/Cost Today"));

    const amps = this.num("number/Breaker Size") || 25;
    $(this, "#bushint").innerHTML = `הפס מראה כמה מהמפסק בשימוש (<bdi dir="ltr">3×${amps}A</bdi>). הקו המקווקו הוא 80%.`;
    for (const p of PHASES) {
      const a = this.num(`sensor/Current L${p.n}`);
      const k = this.num(`sensor/Power L${p.n}`);
      const v = this.num(`sensor/Voltage L${p.n}`);
      const ratio = a / amps;
      const row = $(this, `#ph${p.n}`);
      row.classList.toggle("warn", ratio >= 0.8 && ratio < 0.95);
      row.classList.toggle("crit", ratio >= 0.95);
      $(row, ".fill").style.width = `${isNum(ratio) ? clamp(ratio, 0, 1) * 100 : 0}%`;
      $(row, ".a").textContent = fixed(a, 1);
      $(row, ".k").textContent = fixed(k, 2);
      $(row, ".v").textContent = fixed(v, 0);
    }

    $(this, "#t-month").textContent = money(this.num("sensor/Cost Month"), 0);
    $(this, "#t-fc").textContent = money(this.num("sensor/Forecast Month"), 0);
    $(this, "#t-kwh").textContent = fixed(this.num("sensor/Energy Today"), 1);
    const vs = this.num("sensor/Compared To Yesterday");
    const vsEl = $(this, "#t-vs");
    vsEl.className = "";
    if (!isNum(vs)) {
      vsEl.textContent = "—";
      $(this, "#t-vs-l").textContent = "השוואה לאתמול תופיע אחרי יממה";
    } else {
      const r = Math.round(vs);
      vsEl.textContent = Math.abs(r) <= 5 ? "כמו אתמול" : `${r > 0 ? "+" : "−"}${Math.abs(r)}%`;
      if (r > 5) vsEl.className = "up";
      else if (r < -5) vsEl.className = "down";
      $(this, "#t-vs-l").textContent = "מול אתמול באותה שעה";
    }

    const bl = this.num("sensor/Baseload");
    const blc = this.num("sensor/Baseload Cost");
    $(this, "#base").innerHTML = isNum(bl)
      ? `כשכמעט הכול כבוי הבית צורך <b dir="ltr">${bl.toFixed(2)} kW</b>, בערך <b dir="ltr">${money(blc, 0)}</b> לחודש.`
      : "";
    const pk = this.num("sensor/Peak Today");
    const pt = this.text("text_sensor/Peak Time");
    $(this, "#peak").innerHTML = isNum(pk) ? `שיא היום <b dir="ltr">${pk.toFixed(2)} kW</b>${pt ? ` בשעה <b dir="ltr">${esc(pt)}</b>` : ""}.` : "";
  }

  updatePlan() {
    const price = this.num("sensor/Price");
    const disc = this.num("sensor/Discount");
    const win = this.text("text_sensor/Discount Window");
    $(this, "#price").textContent = isNum(price) ? `₪${price.toFixed(4)}` : "—";
    $(this, "#pricewhy").innerHTML = isNum(disc) && disc > 0
      ? `המחיר עכשיו, אחרי ${disc % 1 ? disc.toFixed(1) : disc.toFixed(0)}% הנחה${win ? ` (${ltrTimes(esc(win.replace(/[\u2066-\u2069]/g, "")))})` : ""}`
      : "המחיר עכשיו, ללא הנחה בשעה זו";
    this.renderPlans(false);

    const plan = this.text("select/Supplier Plan");
    $(this, "#custom").hidden = plan !== "מותאם אישית";

    this.querySelectorAll("[data-num]").forEach((inp) => {
      const id = inp.dataset.num;
      if (this.pending[id] || document.activeElement === inp) return;
      const s = this.state[id];
      if (!s) return;
      const v = parseFloat(s.value);
      if (Number.isFinite(v)) inp.value = String(v);
      if (s.min_value !== undefined) inp.min = s.min_value;
      if (s.max_value !== undefined) inp.max = s.max_value;
      if (s.step !== undefined) inp.step = s.step;
    });
    this.querySelectorAll("[data-switch]").forEach((sw) => {
      const s = this.state[sw.dataset.switch];
      if (s) sw.setAttribute("aria-checked", String(s.value === true || s.state === "ON"));
    });
    const amps = this.num("number/Breaker Size");
    this.querySelectorAll("[data-amps]").forEach((b) => b.setAttribute("aria-pressed", String(+b.dataset.amps === amps)));
  }

  renderPlans(force) {
    const sel = this.get("select/Supplier Plan");
    const options = sel?.option || [];
    const current = sel ? String(sel.value ?? sel.state ?? "") : "";
    const q = $(this, "#q").value.trim();
    const key = `${options.length}|${current}|${q}`;
    if (!force && key === this.plansKey) return;
    this.plansKey = key;

    const list = $(this, "#plans");
    if (!options.length) {
      list.innerHTML = `<p class="hint">טוען את רשימת המסלולים…</p>`;
      return;
    }
    // group by provider (meta from the generated table, else label prefix)
    const groups = new Map();
    for (const opt of options) {
      const meta = PLAN_META[opt] || {};
      if (q && !opt.includes(q) && !(meta.provider || "").includes(q)) continue;
      const prov = meta.provider || "";
      if (!groups.has(prov)) groups.set(prov, []);
      groups.get(prov).push({ opt, meta });
    }
    let html = "";
    for (const [prov, items] of groups) {
      if (prov) html += `<p class="prov">${esc(prov)}</p>`;
      for (const { opt, meta } of items) {
        const checked = opt === current;
        html += `<button class="plan" role="radio" aria-checked="${checked}" data-option="${esc(opt)}">
          <span class="dot" aria-hidden="true"></span>
          <span><span class="t">${esc(meta.plan || opt)}</span>${meta.hours ? `<span class="s">${ltrTimes(esc(meta.hours))}</span>` : ""}</span>
          <span class="pct">${meta.pct ? esc(meta.pct) : ""}</span>
        </button>`;
      }
    }
    list.innerHTML = html || `<p class="hint">לא נמצא מסלול בשם הזה.</p>`;
  }

  updateFirmware() {
    const u = this.get("update/Firmware");
    const cur = u?.current_version || this.text("text_sensor/Firmware Version");
    $(this, "#v-cur").textContent = cur || "—";
    const latest = u ? String(u.value ?? "") : "";
    $(this, "#v-new").textContent = latest || "—";
    const avail = u && /available|update/i.test(String(u.state)) && latest && latest !== cur;
    const btn = $(this, "#v-install");
    btn.disabled = !avail;
    btn.textContent = avail ? `התקנת גרסה ${latest}` : "המכשיר מעודכן";
    $(this, "#v-sum").textContent = !u ? "בדיקת עדכונים דורשת חיבור לאינטרנט." : u.summary || "";
  }

  updateDevice(reading) {
    const crc = this.num("sensor/P1 CRC Errors");
    $(this, "#d-p1").textContent = reading ? "תקין" : "אין";
    $(this, "#d-crc").textContent = isNum(crc) ? String(Math.round(crc)) : "—";
    const rssi = this.num("sensor/WiFi Signal");
    $(this, "#d-wifi").innerHTML = isNum(rssi)
      ? `${rssi > -60 ? "מצוינת" : rssi > -72 ? "טובה" : "חלשה"} <bdi dir="ltr">(${Math.round(rssi)} dBm)</bdi>`
      : this.get("text_sensor/IP Address") ? "חיבור חוטי" : "—";
    $(this, "#d-ip").textContent = this.text("text_sensor/IP Address") || location.hostname;
    $(this, "#d-up").textContent = duration(this.num("sensor/Uptime"));
    const u = this.get("update/Firmware");
    $(this, "#d-ver").textContent = u?.current_version || this.text("text_sensor/Firmware Version") || "—";
  }
}

if (!customElements.get("esp-app")) customElements.define("esp-app", EspApp);
